head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25001";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — availableModify

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25001.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_availableModify", fn: function(){ return ((dma_pageContext.get("availableModify") ?? "")); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

// [A] 초기 목록 미해결 — jldfil25001: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_corpMiscInfoChgList_oncellclick
 * @description grd_corpMiscInfoChgList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_corpMiscInfoChgList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_corpMiscInfoChgList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_corpMiscInfoChgList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["applDateYn"] === 'Y' || r["applDateYn"] !== 'V') { await scwin.goURL("modi", r["bzProcsNo"], r["applDateYn"]); return; }
        /* TODO Stage2: 행 동작 미정의: scwin.alert (열 ?) */ await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.alert'); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_corpMiscInfoChgList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_GoURL_2_onclick
 * @description 「변경신청」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_GoURL_2_onclick = async function(e){
    try {
        await scwin.goURL('req','','Y')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25001.btn_GoURL_2_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_GoURL
 * @description Go URL 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GoURL = async function () {
    try { return await $c.data.downFile("/account/corporationReport.do", "", ($c.util.getComponent("dma_GoURLReq") ? $c.util.getComponent("dma_GoURLReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name goURL
 * @description go URL 처리
 * @param {*} _target _target
 * @param {*} _bzProcsNo _bzProcsNo
 * @param {String} applDateYn applDateYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goURL = async function (_target, _bzProcsNo, applDateYn) {
    (document.corpForm || { elements: [] }).action = "corporationReport.do";
    $c.util.getComponent('dma_GoURLReq').set('method', "searchCorporationReport");
    $c.util.getComponent('dma_GoURLReq').set('viewFlag', _target);
    $c.util.getComponent('dma_GoURLReq').set('applDateYn', applDateYn);
    $c.util.getComponent('dma_GoURLReq').set('bzProcsNo', _bzProcsNo);
    await scwin.tx_fn_GoURL();
};
